mapper.select:
SELECT 
FROM flow_node_instance ni
WHERE ni.instance_id = #{instanceId}
  AND ni.node_key = #{nodeKey}
LIMIT 1

SELECT 
FROM flow_node_instance ni
WHERE ni.instance_id = #{instanceId}
  AND ni.node_seq = #{seq}
ORDER BY IFNULL(ni.dept_id, 0) ASC, ni.id ASC

SELECT COUNT(1)
FROM flow_node_instance ni
WHERE ni.instance_id = #{instanceId}
  AND ni.node_seq = #{seq}
  AND ni.status IN ('pending', 'active', 'waiting_supplement', 'returned')

SELECT COUNT(1)
FROM flow_node_instance ni
WHERE ni.instance_id = #{instanceId}
  AND ni.node_seq = #{seq}
  AND ni.status IN ('approved', 'skipped')

SELECT COUNT(1)
FROM flow_node_instance ni
WHERE ni.instance_id = #{instanceId}

mapper.update:
UPDATE flow_node_instance
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}

UPDATE flow_node_instance
SET approver_ids_json = #{approverIdsJson}, updated_at = NOW()
WHERE id = #{id}

UPDATE flow_node_instance
SET add_sign_chain_json = #{addSignChainJson}, updated_at = NOW()
WHERE id = #{id}

UPDATE flow_node_instance
SET returned_count = returned_count + 1, updated_at = NOW()
WHERE id = #{id}
